import{_ as t,o as s,c as r,a2 as a}from"./chunks/framework.BBXLvvRa.js";const u=JSON.parse('{"title":"Process Automation Best Practices","description":"Why we value process automation best practices over tool-centric features, and how to model, test, version, and operate durable processes.","frontmatter":{"title":"Process Automation Best Practices","description":"Why we value process automation best practices over tool-centric features, and how to model, test, version, and operate durable processes."},"headers":[],"relativePath":"docs/principles/best-practices.md","filePath":"docs/principles/best-practices.md"}'),o={name:"docs/principles/best-practices.md"};function n(i,e,c,l,p,d){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="process-automation-best-practices" tabindex="-1">Process Automation Best Practices <a class="header-anchor" href="#process-automation-best-practices" aria-label="Permalink to &quot;Process Automation Best Practices&quot;">​</a></h1><blockquote><p>Process Automation Best Practices <strong>over</strong> Tool-Centric Features</p></blockquote><p><em>Durable process solutions rest on proven engineering practices, not on the newest item on a vendor&#39;s feature list.</em></p><p>This principle asserts that the way you model, build, test, and operate an automated process matters more than which tool-specific feature you reach for. We hold this because the value of an automated process lives in its clarity, correctness, and maintainability, and those qualities come from sound engineering rather than from any single feature. When a feature shapes your architecture, you trade long-term health for short-term convenience.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>When a tool feature dictates your design, the process becomes hard to reason about and expensive to change. Business rules end up scattered across script tasks, execution listeners, and proprietary expression languages, so no one can tell what the process actually does without opening the engine. Any change then means untangling logic you never isolated in the first place.</p><p>Teams that skip established practices hit the same failures again and again:</p><ul><li><strong>Untestable processes.</strong> Logic buried in the model can only be checked by running the whole engine, so regressions slip through.</li><li><strong>Manual deployments.</strong> Models are clicked into production from a modeler, with no version history, review, or rollback.</li><li><strong>Duplicate side effects.</strong> A retried service task charges a customer twice because the call was never made <a href="https://medium.com/miragon/leveling-up-mastering-the-distributed-transaction-problem-in-zeebe-d4bbbca295d6" target="_blank" rel="noreferrer">idempotent</a> (safe to repeat without changing the result).</li><li><strong>Blind operations.</strong> When a claims-approval process stalls, no one can see where or why, because the process emits no metrics, logs, or traces.</li></ul><h2 id="in-practice" tabindex="-1">In practice <a class="header-anchor" href="#in-practice" aria-label="Permalink to &quot;In practice&quot;">​</a></h2><ul><li><strong>Agree on modeling conventions.</strong> Standardize naming, element usage, and error patterns in <a href="https://www.omg.org/spec/BPMN/" target="_blank" rel="noreferrer">BPMN</a> (Business Process Model and Notation) and <a href="https://www.omg.org/spec/DMN/" target="_blank" rel="noreferrer">DMN</a> (Decision Model and Notation) so any team member can read a diagram.</li><li><strong>Separate orchestration from business logic.</strong> Keep the process model focused on flow and delegate real work to versioned services or workers, so logic stays testable outside the engine.</li><li><strong>Put processes under version control and CI/CD.</strong> Store models as files in <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a> and ship them through the same <a href="https://martinfowler.com/articles/continuousIntegration.html" target="_blank" rel="noreferrer">continuous integration</a> and continuous delivery (CI/CD) pipelines as your code, with automated builds, tests, and releases.</li><li><strong>Design for failure.</strong> Model boundary error events, retries, and compensation explicitly, and make every service call idempotent so retries are safe.</li><li><strong>Automate process tests.</strong> Use engine testing libraries, such as the process test support in Camunda, Operaton, or Flowable, to assert token flow, decision outcomes, and error paths on every commit.</li><li><strong>Make processes observable.</strong> Emit <a href="https://opentelemetry.io/docs/concepts/signals/metrics/" target="_blank" rel="noreferrer">metrics</a>, <a href="https://opentelemetry.io/docs/concepts/signals/logs/" target="_blank" rel="noreferrer">structured logs</a>, and <a href="https://opentelemetry.io/docs/concepts/signals/traces/" target="_blank" rel="noreferrer">traces</a> so you can answer where a claims-approval process is stuck and why.</li></ul><h2 id="what-this-doesn-t-mean" tabindex="-1">What this doesn&#39;t mean <a class="header-anchor" href="#what-this-doesn-t-mean" aria-label="Permalink to &quot;What this doesn&#39;t mean&quot;">​</a></h2><p>This principle does not reject tool features. A capable engine, a good modeler, and prebuilt connectors and templates save real time, and you should use them. The point is one of emphasis and sequencing: let sound practices and patterns shape your architecture first, then adopt a specific feature when it serves that architecture, not the other way around.</p><h2 id="related-principles" tabindex="-1">Related principles <a class="header-anchor" href="#related-principles" aria-label="Permalink to &quot;Related principles&quot;">​</a></h2><ul><li><a href="/docs/principles/open-standards">Open Standards</a>: avoiding lock-in and preferring versioned logic over vendor scripts keeps your models portable across engines.</li><li><a href="/docs/principles/continuous-improvement">Continuous Process Improvement</a>: observability, CI/CD, and small versioned releases are what make ongoing improvement safe.</li></ul>',14)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
